    q = @directed[[b, a]]
    next unless q && incircle(@points[a], @points[b], @points[site], @points[q]).positive?

    remove(a, b, site)
    remove(b, a, q)
    add(a, q, site)
    add(q, b, site)
    check.add([a, q])
    check.add([q, b])
    flips += 1
  end
def add(a, b, c)
  @directed[[a, b]] = c
  @directed[[b, c]] = a
  @directed[[c, a]] = b
end

def remove(a, b, c)
  @directed.delete([a, b])
  @directed.delete([b, c])
  @directed.delete([c, a])
end
